import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CiQ1TEvV.js";const m=JSON.parse('{"title":"About Mneme","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1785115728000}'),i={name:"about.md"};function o(s,e,l,h,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="about-mneme" tabindex="-1">About Mneme <a class="header-anchor" href="#about-mneme" aria-label="Permalink to &quot;About Mneme&quot;">​</a></h1><p>Mneme is a local-document Retrieval-Augmented Generation (RAG) system named after <strong>Mnemosyne</strong>, the Greek goddess of memory in Greek mythology.</p><h2 id="project-goal" tabindex="-1">Project Goal <a class="header-anchor" href="#project-goal" aria-label="Permalink to &quot;Project Goal&quot;">​</a></h2><p>Turn a local document collection into a verifiable, queryable memory. Every answer should be traceable to a specific file, page, and chunk.</p><h2 id="what-mneme-is" tabindex="-1">What Mneme Is <a class="header-anchor" href="#what-mneme-is" aria-label="Permalink to &quot;What Mneme Is&quot;">​</a></h2><ul><li>A <strong>Python CLI</strong> for one-shot and batch document Q&amp;A</li><li>A <strong>bilingual terminal UI</strong> (TUI) for interactive sessions with file watching</li><li>A <strong>hybrid retrieval engine</strong> combining semantic search (ChromaDB + Sentence Transformers) and lexical search (BM25)</li><li>A <strong>Graph RAG</strong> mode for cross-document relationship queries</li><li>A <strong>safety-first</strong> system with explicit data boundaries, endpoint validation, and resource limits</li></ul><h2 id="what-mneme-is-not" tabindex="-1">What Mneme Is Not <a class="header-anchor" href="#what-mneme-is-not" aria-label="Permalink to &quot;What Mneme Is Not&quot;">​</a></h2><ul><li>Not a cloud service — all indexing happens locally</li><li>Not a guarantee that data never leaves your machine — retrieved snippets are sent to your configured LLM endpoint</li><li>Not a replacement for reading the original documents — it augments reading with fast retrieval and summarization</li></ul><h2 id="architecture-principles" tabindex="-1">Architecture Principles <a class="header-anchor" href="#architecture-principles" aria-label="Permalink to &quot;Architecture Principles&quot;">​</a></h2><ol><li><strong>Identity first</strong> — stable <code>source_id</code>, <code>chunk_id</code>, and content hashes prevent index drift</li><li><strong>Versioned mutations</strong> — atomic manifest updates keep vector store, BM25, and graph cache aligned</li><li><strong>Explicit boundaries</strong> — untrusted-document tags separate retrieved text from system instructions</li><li><strong>Measurable quality</strong> — benchmark utilities for Recall@k, MRR, nDCG, and quality gates</li><li><strong>Offline-safe tests</strong> — CI runs without API keys; integration tests are opt-in</li></ol><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><a href="https://github.com/realhenrylan/mneme/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a></p><h2 id="author" tabindex="-1">Author <a class="header-anchor" href="#author" aria-label="Permalink to &quot;Author&quot;">​</a></h2><p>Built by <a href="https://github.com/realhenrylan" target="_blank" rel="noreferrer">Henry Lan</a>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/realhenrylan/mneme" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><a href="https://github.com/realhenrylan/mneme/issues" target="_blank" rel="noreferrer">Issues &amp; Discussions</a></li><li><a href="/MNEME/">Homepage</a></li></ul>',16)])])}const p=a(i,[["render",o]]);export{m as __pageData,p as default};
